        r = Step(machine, dispenser, r.Account, D(0, 1, 0), Refused(AtmStatus.CassetteJammed, 210, 40), N(5, 5, 1));
        r = Step(machine, dispenser, r.Account, D(1, 0, 0), Refused(AtmStatus.CassetteFull, 210, 40), N(5, 5, 1));
