</Project>
EOF
cat /travail/Atm/Atm.csproj; cat > Program.cs <<'EOF'
using Atm;
static NoteCounts N(int f,int t,int c)=>new(f,t,c);
static NoteCounts? Fewest(int amount, NoteCounts a){NoteCounts? best=null;
 for(var f=0;f<=a.Fifties;f++)for(var t=0;t<=a.Twenties;t++)for(var c=0;c<=a.Tens;c++){var x=N(f,t,c);if(x.Value==amount&&(best is null||x.Total<best.Value.Total))best=x;}return best;}
Denomination?[] jams=[null,Denomination.Fifty,Denomination.Twenty,Denomination.Ten];
int[] amounts=[-10,0,5,..Enumerable.Range(1,22).Select(i=>i*10)];
long diff=0,total=0; var samples=new List<string>();
for(int f=0;f<=5;f++)for(int t=0;t<=5;t++)for(int c=0;c<=5;c++)foreach(var j in jams){
 var stock=N(f,t,c); var av=N(j==Denomination.Fifty?0:f,j==Denomination.Twenty?0:t,j==Denomination.Ten?0:c);
 foreach(var amount in amounts){ var comb = amount>0&&amount%10==0? Fewest(amount,av):null;
  for(int b=0;b<=250;b+=5)for(int w=0;w<=200;w+=10){
   var acc=new AccountState(b,w); AtmResult exp; NoteCounts es=stock;
   if(amount<=0||amount%10!=0) exp=new(AtmStatus.InvalidAmount,default,0,acc);
   else if(w+amount>200) exp=new(AtmStatus.DailyLimitExceeded,default,0,acc);
   else { var fee=amount>100?5:0; if(amount+fee>b) exp=new(AtmStatus.InsufficientFunds,default,0,acc);
     else if(comb is not {} n) exp=new(AtmStatus.CannotDispense,default,0,acc);
     else { exp=new(AtmStatus.Ok,n,fee,new(b-amount-fee,w+amount)); es=stock-n; } }
   var d=new MoneyDispenser(stock,j); var r=new CashMachine(d).Execute(acc,new Operation.Withdraw(amount)); total++;
   if(r!=exp||d.Stock!=es){diff++; if(samples.Count<15)samples.Add($"b={b} w={w} stock={stock} jam={j} W{amount}: got {r} exp {exp}");}
  }}
 for(int m=0;m<8;m++){var dep=N(m&1,(m>>1)&1,(m>>2)&1);
  for(int b=0;b<=250;b+=5)for(int w=0;w<=200;w+=10){var acc=new AccountState(b,w);AtmResult exp;NoteCounts es=stock;
   if(dep.Total==0)exp=new(AtmStatus.InvalidAmount,default,0,acc);
   else if(j is {} jj && dep.Of(jj)>0)exp=new(AtmStatus.CassetteJammed,default,0,acc);
   else if((stock+dep) is {Fifties:>5} or {Twenties:>5} or {Tens:>5})exp=new(AtmStatus.CassetteFull,default,0,acc);
   else {exp=new(AtmStatus.Ok,default,0,acc with{Balance=b+dep.Value});es=stock+dep;}
   var d=new MoneyDispenser(stock,j); var r=new CashMachine(d).Execute(acc,new Operation.Deposit(dep)); total++;
   if(r!=exp||d.Stock!=es){diff++; if(samples.Count<15)samples.Add($"b={b} w={w} stock={stock} jam={j} D{dep}: got {r} exp {exp}");}
  }}
}
Console.WriteLine($"diff {diff} / {total}"); foreach(var s in samples)Console.WriteLine(s);
EOF
