mkdir -p /tmp/mut && cat > /tmp/mut/gen.py <<'EOF'
import re, json
src=open('/tmp/CashMachine.orig.cs').read().split('\n')
muts=[]
ids=['amount','fee','account.Balance','account.WithdrawnToday','afterFifties','rest','fifties','twenties','remaining.Total','room']
rel=['>','>=','<','<=','==','!=']
for i,l in enumerate(src):
    if l.strip().startswith(('///','//','public const','namespace')): continue
    # relational
    for m in re.finditer(r'(?<![=<>!])(>=|<=|==|!=|>|<)(?![=>])',l):
        if '=>' in l[m.start()-1:m.end()+1]: continue
        for r in rel:
            if r!=m.group(1): muts.append((i,l[:m.start()]+r+l[m.end():]))
    for a in ids:
        for m in re.finditer(r'(?<![\w.])'+re.escape(a)+r'(?![\w])',l):
            for b in ids:
                if b!=a: muts.append((i,l[:m.start()]+b+l[m.end():]))
    for m in re.finditer(r'(?<=\s)([+-])(?=\s)',l):
        muts.append((i,l[:m.start()]+('-' if m.group(1)=='+' else '+')+l[m.end():]))
    for m in re.finditer(r'\b(\d+)\b',l):
        v=int(m.group(1))
        for nv in {v-1,v+1,0,1,5,10,20,50}:
            if nv!=v and nv>=0: muts.append((i,l[:m.start()]+str(nv)+l[m.end():]))
    for c in ['DailyLimit','FeeThreshold','WithdrawalFee','CassetteCapacity','MaxNotesPerPass']:
        for m in re.finditer(r'\b'+c+r'\b',l):
            for d in ['DailyLimit','FeeThreshold','WithdrawalFee','CassetteCapacity','MaxNotesPerPass','(%s - 1)'%c,'(%s + 1)'%c]:
                if d!=c: muts.append((i,l[:m.start()]+d+l[m.end():]))
json.dump(muts,open('/tmp/mut/muts.json','w'))
print(len(muts))
EOF
python3 /tmp/mut/gen.py

